import sys

def count_numbers_with_power_of_two(n, e):
    power_of_two = bin(2**e)[2:]  # Convert 2^e to binary string
    count = 0

    def dfs(current):
        nonlocal count
        if int(current, 2) > n:
            return
        if power_of_two in current:
            count += 1
        for digit in '01':
            dfs(current + digit)

    dfs('')
    return count

