def count_numbers_containing_power_of_2(n, e):
    import sys
    from itertools import combinations

    def get_digits_of_power_of_2(e):
        return set(str(2**e))

    def is_subsequence(a, b):
        """ Check if string a is a subsequence of string b. """
        it = iter(b)
        return all(char in it for char in a)

    def count_valid_numbers(upper_bound_str, digits_set):
        length = len(upper_bound_str)
        count = 0

        # Iterate over all possible lengths of the subsequences
        for sub_len in range(1, length + 1):
            # Generate all combinations of positions in the number
            for pos_combo in combinations(range(length), sub_len):
                candidate_digits = [upper_bound_str[i] for i in pos_combo]
                candidate_digits_str = ''.join(candidate_digits)
                if is_subsequence(candidate_digits_str, upper_bound_str) and set(candidate_digits_str).issubset(digits_set):
                    count += 1

        return count

